<style>
.reset-page{min-height:100dvh;display:grid;grid-template-columns:minmax(360px,46%) minmax(0,54%);background:#f7f7f1}.reset-brand{padding:clamp(38px,5vw,76px);background:radial-gradient(circle at 15% 15%,#30332b 0,transparent 28%),linear-gradient(145deg,#131413,#1c1e1a);color:#fff;display:flex;flex-direction:column}.reset-brand>a{display:flex;align-items:center;gap:14px;color:#fff;text-decoration:none;letter-spacing:.12em}.reset-brand img{width:94px;height:94px;border-radius:50%;object-fit:contain;background:#fff}.reset-brand>div{margin:auto 0;max-width:540px}.reset-brand p,.reset-eyebrow{font-size:12px;letter-spacing:.18em;color:#b4bf1a;margin:0 0 15px}.reset-brand h1{font-size:clamp(42px,4.3vw,68px);letter-spacing:-.045em;line-height:1.02;margin:0 0 22px}.reset-brand span{font-size:18px;line-height:1.7;color:#c4c7c0}.reset-brand small{color:#858982}.reset-form{display:grid;place-items:center;padding:clamp(28px,6vw,90px);background:radial-gradient(circle at 100% 0,#f0f1d8 0,transparent 32%),#f7f7f1;overflow-y:auto}.reset-inner{width:min(520px,100%)}.reset-inner h2{font-size:clamp(32px,3vw,44px);letter-spacing:-.035em;margin:8px 0 10px}.reset-inner>.muted{font-size:16px;line-height:1.65;margin:0 0 30px}.reset-inner .field{margin-bottom:21px}.reset-inner .control{display:block;width:100%;min-height:54px;border-radius:13px;font-size:16px}.reset-button{width:100%;min-height:56px;border:0;border-radius:13px;padding:15px 20px;background:#171817;color:#fff;font-size:16px;font-weight:750;display:flex;align-items:center;justify-content:space-between;cursor:pointer;box-shadow:0 10px 24px rgba(23,24,23,.16)}.reset-button:hover{background:#30322e}.return-login{display:block;width:max-content;margin:22px auto 0;color:#626b00;font-weight:750;text-underline-offset:4px}.reset-success{margin-bottom:22px;padding:14px 16px;border:1px solid #b8d6a9;border-radius:11px;background:#f0f8e9;color:#355126;line-height:1.5}.reset-inner .error{margin:7px 0 0;color:#a61b1b;font-size:13px}@media(max-width:800px){.reset-page{grid-template-columns:1fr}.reset-brand{min-height:210px;padding:24px}.reset-brand img{width:68px;height:68px}.reset-brand>div{margin:22px 0 0}.reset-brand h1{font-size:31px;margin-bottom:0}.reset-brand span,.reset-brand small{display:none}.reset-form{min-height:calc(100dvh - 210px);padding:34px 20px 48px;place-items:start center}}@media(max-width:480px){.reset-brand{min-height:166px}.reset-brand img{width:56px;height:56px}.reset-brand h1{font-size:26px}.reset-form{min-height:calc(100dvh - 166px);padding:25px 16px 40px}.reset-inner h2{font-size:30px}.reset-inner .control{min-height:50px}}
</style>
